def prep(t):
 t=re.sub(r"@\w+"," ",re.sub(r"https?://\S+|www\.\S+"," ",t)).lower()
 return re.sub(r"\s+"," ",re.sub(r"[^\w\s]"," ",re.sub(r"&\w+;"," ",t))).strip()[:1000]
def table():
 global W
 if W is None:
  n=0
  for c in S:n=n<<15|ord(c)-19968
  o=len(S)*15
  def G(w):
   nonlocal o;o-=w;return n>>o&(1<<w)-1
  q=[G(14)for _ in range(G(16))];s=np.array([G(16)for _ in range(96)],np.uint16).view(np.float16).astype(f);m=G(8)-128;y=[];u=[];a=0
  for i,v in enumerate(q):u.append(a);y+=[i]*v;a+=v
  B=[[comb(c,i)for c in range(97)]for i in range(len(q)//4+1)];w=np.zeros(2359296,f);e=np.zeros(24576,f);r=0
  while r<24576:
   x=G(G(20))
   for r in range(r,r+256):
    t=x&16383;j=y[t];x=q[j]*(x>>14)+t-u[j];k=j>>2
    if k:
     e[r]=j%4+m;M=B[k][96];v=x%M;x//=M;g=x&(1<<k)-1;x>>=k;c=96
     for i in range(k,0,-1):
      c-=1;b=B[i]
      while b[c]>v:c-=1
      v-=b[c];w[r*96+c]=1-2*(g>>i-1&1)
   r+=1
  W=w.reshape(-1,96)*s*np.exp2(e/2)[:,None]
 return W
def embed(d):
 X=vstack([hstack([H(n_features=8192,ngram_range=(1,2),alternate_sign=False,norm=None,dtype=f).transform(d[i:i+4000]),H(n_features=16384,ngram_range=(3,5),analyzer="char_wb",alternate_sign=False,norm=None,dtype=f).transform(d[i:i+4000])]).tocsr()for i in range(0,len(d),4000)]).tocsr()
 X.data=np.log1p(X.data);X.data*=(np.log((X.shape[0]+1.)/(np.bincount(X.indices,minlength=X.shape[1])+1.))+1.).astype(f)[X.indices];X=N(X,copy=False)
 Z=np.vstack([np.asarray(X[i:i+4000]@table(),f)for i in range(0,len(d),4000)]);z=np.abs(Z).sum(1)<1e-9
 if z.any():Z[z]=np.random.RandomState(0).normal(size=(int(z.sum()),96))*1e-3
 return N(Z)
def nn(Z,k):return NearestNeighbors(n_neighbors=min(k,len(Z)),metric="cosine").fit(Z).kneighbors(Z)
def sm(Z,k,a,t):
 x=nn(Z,k+1)[1][:,1:]
 for _ in range(t):Z=N((1-a)*Z+a*Z[x].mean(1))
 return Z
def langs(l,d):
 for j in np.flatnonzero(np.bincount(l)>39):
  F=np.flatnonzero(l==j);D=[d[i]for i in F]
  try:
   U=TruncatedSVD(24,random_state=0).fit_transform(T(binary=True,use_idf=False,min_df=4,token_pattern=r"\b[^\W\d_]{2,}\b").fit_transform(D));z=abs(U).sum(1)<1e-9;U[z]=np.random.RandomState(0).randn(z.sum(),24);g=fcluster(linkage(sm(N(U),15,.4,4),"average","cosine"),.6,"distance")
   s=np.array([np.argmax([abs(len(x)/8-.1)]+[len(re.findall(p,x))for p in("[Ѐ-ԯ]","[一-鿿぀-\u30ff가-힯]","[؀-ۿ]","[֐-׿]","[฀-๿]","[ऀ-ॿ]")])for x in D]);g=np.where(s,9999+s,g);u,c=np.unique(g,return_counts=True);u=u[c>24]
   C=T(analyzer="char",ngram_range=(1,3),use_idf=False,sublinear_tf=True,min_df=2).fit_transform(D);m=fcluster(linkage(np.vstack([np.asarray(C[g==b].mean(0))for b in u]),"single","cosine"),.13,"distance");G=sum((g==b)*x for b,x in zip(u,m));G[G==np.bincount(G)[1:].argmax()+1]=0;l[F]=np.where(G,l.max()+G,j)
  except Exception:pass
def core(Z,p,d=0,g=0):
 k,a,t,s,r=p[:5];n=len(Z);Y=sm(Z,k,a,t);E,J=nn(Y,31);e=E[:,min(15,n-1)];L=linkage(Y,"average","cosine");o=np.argsort(-e)[:int(n*r)]
 if d and n>=500:
  try:
   y=fcluster(L,90,"maxclust");m=np.ones(n,bool);m[o]=False;m&=np.bincount(y)[y]>=10;w=dict(max_features=60000,min_df=2,max_df=.5,sublinear_tf=True,dtype=f)
   X=N(hstack([T(ngram_range=(1,2),**w).fit_transform(d),T(analyzer="char_wb",ngram_range=(3,5),**w).fit_transform(d)]).tocsr());P=RidgeClassifier(alpha=10.).fit(X[m],y[m]).decision_function(X);P=N(P-P.mean(1,keepdims=True))
   return core(N(np.hstack([Z,.75*P])),p,0,(e,P,np.log1p(X.getnnz(1)),p is A and d,X))
  except Exception:pass
 l=fcluster(L,max(2,min(s,n//8)),"maxclust").astype(np.int64)
 if g:
  if g[3]:langs(l,g[3])
  try:
   u,P,z=g[:3];X=g[4];I=np.arange(n);K=~np.isin(I,o);C=np.eye(l.max()+1)[l]*K[:,None];b=C.sum(0);m=b[l];c=C.T@Y/np.maximum(b,1)[:,None];v=Y@N(c).T;v[:,b<1]=-1;h=v[I,l];v[I,l]=-1;x=np.log(e+1e-6);D=np.array([np.median(e[i>0])if i.any()else 1 for i in C.T]);q=np.sort(P,1);G=np.argsort(np.argsort([e,u]))/n;V=J[:,1:16]
   F=np.c_[G[0],x-np.median(x),G[1],np.log(E[:,[5,30]]+1e-6)-x[:,None],q[:,-1],q[:,-1]-q[:,-2],np.log(m+~K),(l[V]==l[:,None]).mean(1),K[V].mean(1),h,h-v.max(1),1-m/np.bincount(l)[l],x-np.log(D[l]+1e-6),(c*c).sum(1)[l],(C.T@(P==q[:,-1:])).argmax(1)[l]==P.argmax(1),z-np.median(z)]@p[5][:17]
   if len(p[5])>17:
    U=np.zeros(n)
    for i in range(0,n,1000):j=I[i:i+1000];G=(X[j]@X.T).toarray();G[j-i,j]=-1;U[j]=(l[np.argpartition(-G,10)[:,:10]]==l[j,None]).mean(1)
    G=X@N(X.T@C,axis=0);w=G[I,l];G[I,l]=-1;F+=p[5][17]*U+p[5][18]*(w-G.max(1))
   F[m<1]=9e9;o=np.argsort(-F)[:len(o)]
  except Exception:pass
